import factory = require( './index' );

/**
* TESTS
*/

// The factory function returns a function...
{
	const rng = factory();
	rng(); // $ExpectType number
	rng.normalized(); // $ExpectType number
	rng.copy(); // $ExpectType NullaryFunction
}

// The factory function accepts a seed option...
{
	const rng = factory( {
		'seed': 1234
	} );
	rng(); // $ExpectType number
}

// The factory function accepts a state option...
{
	const state = new Uint32Array( 4 );
	const rng = factory( {
		'state': state
	} );
	rng(); // $ExpectType number
}

// The factory function accepts both seed and state options...
{
	const state = new Uint32Array( 4 );
	const rng = factory( {
		'seed': 1234,
		'state': state
	} );
	rng(); // $ExpectType number
}

// The factory function accepts a copy option...
{
	const rng = factory( {
		'copy': true
	} );
	rng(); // $ExpectType number
}

// The factory function returns an object with NAME property...
{
	const rng = factory();
	String( rng.NAME ); // $ExpectType string
}

// The factory function returns an object with seed property...
{
	const rng = factory();
	Number( rng.seed ); // $ExpectType number
}

// The factory function returns an object with state property (setter)...
{
	const rng = factory();
	const state = new Uint32Array( 4 );
	rng.state = state;
}

// The factory function returns an object with toJSON method...
{
	const rng = factory();
	rng.toJSON(); // $ExpectType { type: string; name: string; state: Uint32Array; params: unknown[]; }
}

// The factory function returns an object with copy method...
{
	const rng = factory();
	rng.copy(); // $ExpectType NullaryFunction
}

// The factory function returns an object with normalized method...
{
	const rng = factory();
	rng.normalized(); // $ExpectType number
}

// Test that factory can be called with options parameter...
{
	const rng = factory( {
		'seed': 12345,
		'copy': false
	} );
	rng(); // $ExpectType number
	rng.normalized(); // $ExpectType number
	rng.copy(); // $ExpectType NullaryFunction
}

// Test that state array must be Uint32Array...
{
	const rng1 = factory();
	const rng2 = factory( {
		'state': rng1.state
	} );
	rng2(); // $ExpectType number
}

// Test that seed must be a number...
{
	const rng = factory( {
		'seed': 999
	} );
	rng(); // $ExpectType number
}

// Test getting and setting state...
{
	const rng1 = factory( {
		'seed': 42
	} );

	rng1();
	rng1();

	const rng2 = factory( {
		'state': rng1.state
	} );

	rng2(); // $ExpectType number
}

// Test copy functionality...
{
	const rng1 = factory( {
		'seed': 100
	} );

	const rng2 = rng1.copy();

	rng1(); // $ExpectType number
	rng2(); // $ExpectType number
}

// Test normalized output...
{
	const rng = factory( {
		'seed': 555
	} );

	rng.normalized(); // $ExpectType number
}

// Test toJSON serialization...
{
	const rng = factory( {
		'seed': 777
	} );

	rng.toJSON(); // $ExpectType { type: string; name: string; state: Uint32Array; params: unknown[]; }
}

// Test NAME constant...
{
	const rng = factory();
	String( rng.NAME ); // $ExpectType string
}

// Test seed property...
{
	const rng = factory( {
		'seed': 1234
	} );

	Number( rng.seed ); // $ExpectType number
}

// Test consecutive generation...
{
	const rng = factory( {
		'seed': 2000
	} );

	rng(); // $ExpectType number
	rng(); // $ExpectType number
	rng(); // $ExpectType number
}
